import sys

s = sys.stdin.read().strip()
n = len(s)

# dp[pos][mod][xd] = number of ways
# xd = chosen digit for 'X' or 10 meaning None chosen yet
from functools import lru_cache

@lru_cache(None)
def dp(pos, mod, xd):
    if pos == n:
        return 1 if mod == 0 else 0

    ch = s[pos]
    total = 0

    # generate possible digits for this position
    cand = []
    if ch == '_':
        cand = range(10)
    elif ch == 'X':
        if xd == 10:
            cand = range(10)
        else:
            cand = [xd]
    else:  # fixed digit
        cand = [int(ch)]

    for d in cand:
        # first-position leading zero check (disallow if length>1)
        if pos == 0:
            if n > 1 and d == 0:
                continue

        nxd = xd
        if ch == 'X' and xd == 10:
            nxd = d

        total += dp(pos + 1, (mod * 10 + d) % 25, nxd)

    return total

