import heapq
import sys
from collections import defaultdict

def compute_longest_palindrome_starting_at(s):
    n = len(s)
    if n == 0:
        return []
    P = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 0
        if i <= r:
            k = min(r - i, P[l + i - l])
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        P[i] = k
        if i + k - 1 > r:
            l = i - k
            r = i + k - 1
    events = []
    for c in range(n):
        L_bound = c - P[c]
        R_bound = c + P[c]
        events.append((L_bound, c + P[c], 'add'))
        events.append((R_bound + 1, c + P[c], 'remove'))
    events.sort(key=lambda x: x[0])
    heap = []
    removals = defaultdict(int)
    L_arr = [0] * n
    for i in range(n):
        while events and events[0][0] == i:
            pos, val, typ = events.pop(0)
            if typ == 'add':
                heapq.heappush(heap, -val)
            else:
                removals[val] += 1
        while heap and removals.get(-heap[0], 0) > 0:
            val = -heapq.heappop(heap)
            removals[val] -= 1
        if heap:
            max_val = -heap[0]
            L_arr[i] = max_val - i + 1
        else:
            L_arr[i] = 0
    return L_arr

def compute_longest_palindrome_ending_at(s):
    n = len(s)
    if n == 0:
        return []
    t = s[::-1]
    L_start = compute_longest_palindrome_starting_at(t)
    L_end = [0] * n
    for i in range(n):
        L_end[i] = L_start[n-1-i]
    return L_end

def find_longest_common_substring(a, b):
    n = len(a)
    m = len(b)
    low, high = 1, min(n, m)
    k0 = 0
    while low <= high:
        mid = (low + high) // 2
        if find_common_substring(a, b, mid):
            k0 = mid
            low = mid + 1
        else:
            high = mid - 1
    return k0

def find_common_substring(a, b, k):
    if k <= 0:
        return False
    hash_set = {}
    for j in range(len(b) - k + 1):
        substr = b[j:j+k]
        h = hash(substr)
        hash_set[h] = j
    for i in range(len(a) - k + 1):
        substr = a[i:i+k]
        h = hash(substr)
        if h in hash_set:
            return True
    return False

def main():
    data = sys.stdin.read().splitlines()
    q = int(data[0].strip())
    index = 1
    results = []
    for _ in range(q):
        a = data[index].strip()
        b = data[index+1].strip()
        index += 2
        rev_b = b[::-1]
        k0 = find_longest_common_substring(a, rev_b)
        if k0 == 0:
            results.append("-1")
            continue
        L_a_start = compute_longest_palindrome_starting_at(a)
        L_b_end = compute_longest_palindrome_ending_at(b)
        hash_set = {}
        for j in range(len(rev_b) - k0 + 1):
            substr = rev_b[j:j+k0]
            h = hash(substr)
            hash_set[h] = j
        best_candidate = None
        total_length = -1
        for i in range(len(a) - k0 + 1):
            substr_a = a[i:i+k0]
            h = hash(substr_a)
            if h in hash_set:
                j = hash_set[h]
                start_b = len(b) - j - k0
                if i + k0 < len(a):
                    L1 = L_a_start[i + k0]
                    s_b_common = b[len(b) - j - k0 : len(b) - j]
                    s_a_part = a[i:i+k0+L1]
                    candidate1 = s_a_part + s_b_common
                    total1 = 2 * k0 + L1
                    if total1 > total_length or (total1 == total_length and candidate1 < best_candidate):
                        best_candidate = candidate1
                        total_length = total1
                if start_b - 1 >= 0:
                    L2 = L_b_end[start_b - 1]
                    s_b_palindrome = b[start_b - L2 : start_b]
                    s_b_total = s_b_palindrome + b[len(b) - j - k0 : len(b) - j]
                    candidate2 = a[i:i+k0] + s_b_total
                    total2 = 2 * k0 + L2
                    if total2 > total_length or (total2 == total_length and candidate2 < best_candidate):
                        best_candidate = candidate2
                        total_length = total2
        if best_candidate is None:
            results.append("-1")
        else:
            results.append(best_candidate)
    for res in results:
        print(res)

if __name__ == '__main__':
    main()
