import sys

def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    t = data[0]
    idx = 1
    out_lines = []
    for _ in range(t):
        n = data[idx]
        idx += 1
        xs = data[idx:idx+n]
        idx += n

        parent = list(range(n))
        rank = [0]*n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # build edges
        for i in range(n):
            xi = xs[i]
            for j in range(i+1, n):
                if abs(xi - xs[j]) <= 2:
                    union(i, j)

        comp_size = {}
        for i in range(n):
            r = find(i)
            comp_size[r] = comp_size.get(r, 0) + 1

        sizes = comp_size.values()
        out_lines.append(f"{min(sizes)} {max(sizes)}")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
