import sys

def is_leap(x, A):
    """Return True if x is a generalized leap year for sequence A."""
    for idx, a in enumerate(A, start=1):
        if x % a == 0:
            return idx % 2 == 1  # odd -> leap, even -> not
    # No divisor found
    return len(A) % 2 == 0  # even n -> leap, odd n -> not

