import sys

# ---------- DSU ----------
class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))  # 1-indexed

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr != yr:
            self.parent[yr] = xr

# ---------- Solver ----------
def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    t = int(data[0])
    out_lines = []
    idx = 1
    for _ in range(t):
        s = data[idx].strip()
        idx += 1
        n = len(s)
        dsu = DSU(n)
        # merge equal edges
        for i in range(1, n + 1):
            j = i % n + 1
            if s[i - 1] == 'E':
                dsu.union(i, j)
        # check not-equal edges
        possible = True
        for i in range(1, n + 1):
            j = i % n + 1
            if s[i - 1] == 'N':
                if dsu.find(i) == dsu.find(j):
                    possible = False
                    break
        out_lines.append("YES" if possible else "NO")
    sys.stdout.write("\n".join(out_lines))

# ---------- Main ----------
if __name__ == "__main__":
    solve()
