import sys
from collections import Counter

def parse_block(lines):
    counter = Counter()
    for line in lines:
        if not line.strip():
            continue
        parts = line.strip().split(',')
        if len(parts) != 2:
            continue
        try:
            cust = int(parts[0].strip())
            # day = int(parts[1].strip())  # day is not needed
            counter[cust] += 1
        except ValueError:
            continue
    return counter

def main():
    raw_lines = sys.stdin.read().splitlines()
    # Find the blank line separating the two blocks
    sep_index = None
    for i, line in enumerate(raw_lines):
        if line.strip() == '':
            sep_index = i
            break
    if sep_index is None:
        # No separator found; treat entire input as one block
        block1 = raw_lines
        block2 = []
    else:
        block1 = raw_lines[:sep_index]
        block2 = raw_lines[sep_index+1:]

    counter1 = parse_block(block1)
    counter2 = parse_block(block2)

    common_customers = sorted(set(counter1) & set(counter2))
    for cust in common_customers:
        total = counter1[cust] + counter2[cust]
        print(f"{cust} {total}")

if __name__ == "__main__":
    main()
