    def get_prime_factors(num):
        factors = defaultdict(int)
        d = 2
        while d * d <= num:
            while num % d == 0:
                factors[d] += 1
                num //= d
            d += 1
        if num > 1:
            factors[num] += 1
        return factors

    # Get prime factorization for each number
    factorizations = []
    for num in a:
        factorizations.append(get_prime_factors(num))

    count = 0

    # For each pair (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            # Multiply the factorizations
            combined = factorizations[i].copy()
            for prime, exp in factorizations[j].items():
                combined[prime] += exp

            # Check if all exponents are divisible by k
            valid = True
            for exp in combined.values():
                if exp % k != 0:
                    valid = False
                    break

            if valid:
                count += 1

    print(count)

