import sys
sys.setrecursionlimit(10000)

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    grid = data[1:n+1]

    free_cells = []
    idx_map = {}
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                idx = len(free_cells)
                free_cells.append((i, j))
                idx_map[(i, j)] = idx

    F = len(free_cells)
    if F == 0:
        print("YES")
        return

    # Directions
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    rows = []          # list of list of indices
    rows_mask = []     # bitmask of indices
    col_rows = [[] for _ in range(F)]  # for each column, list of row indices covering it

    # Build rows
    for idx, (i, j) in enumerate(free_cells):
        # try center at (i,j)
        ok = True
        neigh = []
        for dx,dy in dirs:
            ni, nj = i+dx, j+dy
            if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] == '.':
                neigh.append(idx_map[(ni,nj)])
            else:
                ok = False
                break
        if ok:
            row = [idx] + neigh
            rows.append(row)
            mask = 0
            for v in row:
                mask |= 1 << v
            rows_mask.append(mask)
            r_index = len(rows) - 1
            for v in row:
                col_rows[v].append(r_index)

    if not rows:
        print("NO")
        return

    # Quick check: every free cell must appear in at least one row
    for col in range(F):
        if not col_rows[col]:
            print("NO")
            return

    all_bits = (1 << F) - 1
    memo = set()

    def dfs(avail_bits):
        if avail_bits == 0:
            return True
        if avail_bits in memo:
            return False

        # choose column with minimal options
        bits = avail_bits
        min_col = -1
        min_count = None

        while bits:
            lsb = bits & -bits
            col = (lsb.bit_length() - 1)
            count = 0
            for r in col_rows[col]:
                if rows_mask[r] & avail_bits == rows_mask[r]:
                    count += 1
                    if min_count is not None and count >= min_count:
                        break
            if min_count is None or count < min_count:
                min_count = count
                min_col = col
                if count == 0:
                    break
            bits ^= lsb

        if min_col == -1 or min_count == 0:
            memo.add(avail_bits)
            return False

        for r in col_rows[min_col]:
            if rows_mask[r] & avail_bits != rows_mask[r]:
                continue
            new_avail = avail_bits & ~rows_mask[r]
            if dfs(new_avail):
                return True

        memo.add(avail_bits)
        return False

    result = dfs(all_bits)
    print("YES" if result else "NO")

if __name__ == "__main__":
    solve()
