import collections
import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print(0)
        return

    n, m, k = map(int, data[0].split())
    grid = []
    index = 1
    for i in range(n):
        block = []
        for j in range(m):
            s = data[index].strip()
            block.append(s)
            index += 1
        grid.append(block)
        if i < n-1:
            index += 1

    working = []
    for i in range(n):
        for j in range(m):
            for l in range(k):
                if grid[i][j][l] == '1':
                    working.append((i, j, l))

    if not working:
        print(0)
        return

    critical_count = 0
    for v in working:
        i, j, l = v
        U = set()
        q = collections.deque()
        q.append(v)
        U.add(v)
        dirs_rev = [(-1,0,0), (0,-1,0), (0,0,-1)]
        while q:
            i0, j0, l0 = q.popleft()
            for di, dj, dl in dirs_rev:
                ni, nj, nl = i0+di, j0+dj, l0+dl
                if 0 <= ni < n and 0 <= nj < m and 0 <= nl < k:
                    if grid[ni][nj][nl] == '1' and (ni, nj, nl) not in U:
                        U.add((ni, nj, nl))
                        q.append((ni, nj, nl))

        W = set()
        q = collections.deque()
        q.append(v)
        W.add(v)
        dirs_fwd = [(1,0,0), (0,1,0), (0,0,1)]
        while q:
            i0, j0, l0 = q.popleft()
            for di, dj, dl in dirs_fwd:
                ni, nj, nl = i0+di, j0+dj, l0+dl
                if 0 <= ni < n and 0 <= nj < m and 0 <= nl < k:
                    if grid[ni][nj][nl] == '1' and (ni, nj, nl) not in W:
                        W.add((ni, nj, nl))
                        q.append((ni, nj, nl))

        if len(U) < 2 or len(W) < 2:
            continue

        critical = False
        for u in U:
            if u == v:
                continue
            reachable = set()
            q = collections.deque()
            q.append(u)
            reachable.add(u)
            while q:
                i0, j0, l0 = q.popleft()
                for di, dj, dl in dirs_fwd:
                    ni, nj, nl = i0+di, j0+dj, l0+dl
                    if 0 <= ni < n and 0 <= nj < m and 0 <= nl < k:
                        if grid[ni][nj][nl] == '1' and (ni, nj, nl) != v and (ni, nj, nl) not in reachable:
                            reachable.add((ni, nj, nl))
                            q.append((ni, nj, nl))
            if reachable.issuperset(W - {v}):
                continue
            else:
                critical = True
                break

        if critical:
            critical_count += 1

    print(critical_count)

if __name__ == "__main__":
    main()
