class Dice(object):

	def __init__(self, faces):
		self.top = faces[0]
		self.south = faces[1]
		self.east = faces[2]
		self.west = faces[3]
		self.north = faces[4]
		self.bottom = faces[5]
		self.values = (self.top, self.south, self.east, self.west, self.north, self.bottom)

	def rotate(self, dir):
		if dir == 'N':
			temp = self.top
			self.top = self.south
			self.south = self.bottom
			self.bottom = self.north
			self.north = temp
		elif dir == 'S':
			temp = self.top
			self.top = self.north
			self.north = self.bottom
			self.bottom = self.south
			self.south = temp
		elif dir == 'E':
			temp = self.top
			self.top = self.west
			self.west = self.bottom
			self.bottom = self.east
			self.east = temp
		elif dir == 'W':
			temp = self.top
			self.top = self.east
			self.east = self.bottom
			self.bottom = self.west
			self.west = temp
		elif dir == 'R':
			self.spin()
		elif dir == 'L':
			self.spin(count=3)
		return self.top

	def get_top_value(self):
		return self.top

	def get_bottom_value(self):
		return self.bottom

	def get_east_value(self):
		return self.east

	def get_west_value(self):
		return self.west

	def get_north_value(self):
		return self.north

	def get_south_value(self):
		return self.south

	def spin(self, count=1):
		for i in range(count):
			temp = self.south
			self.south = self.east
			self.east = self.north
			self.north = self.west
			self.west = temp

	def place(self, upper, front):
		if upper not in self.values or front not in self.values:
			raise ValueError
		if upper == self.top:
			pass
		elif upper == self.east:
			self.rotate('W')
		elif upper == self.west:
			self.rotate('E')
		elif upper == self.north:
			self.rotate('S')
		elif upper == self.south:
			self.rotate('N')
		else:
			self.rotate('N')
			self.rotate('N')
		count = 0
		while front != self.south:
			self.spin()
			count += 1
			if count > 3:
				raise ValueError

	def is_identical(self, dice):
		my_v = sorted(list(self.values))
		d_v = sorted(list(dice.values))
		if my_v != d_v:
			return False
		try:
			dice.place(self.get_top_value(), self.get_south_value())
		except ValueError:
			return False
		if self.get_east_value() != dice.get_east_value():
			return False
		self.spin()
		try:
			dice.place(self.get_top_value(), self.get_south_value())
		except ValueError:
			return False
		if self.get_east_value() != dice.get_east_value():
			return False
		self.spin()
		try:
			dice.place(self.get_top_value(), self.get_south_value())
		except ValueError:
			return False
		if self.get_east_value() != dice.get_east_value():
			return False
		self.spin()
		try:
			dice.place(self.get_top_value(), self.get_south_value())
		except ValueError:
			return False
		if self.get_east_value() != dice.get_east_value():
			return False
		return True

def process_commands(d, cmds):
	total = d.get_top_value()
	for cmd in cmds:
		total += d.rotate(cmd[0])
	return total
while True:
	num = int(input())
	if num == 0:
		break
	commands = [input().strip() for _ in range(num)]
	d = Dice([1, 2, 3, 4, 5, 6])
	result = process_commands(d, commands)
	print(result)

